
#[test]
fn borrowed_static_paged_origin_source8194_exact_body_and_physical4096(){
 use semio_framework_value::{NativeEncodeControl,paged_text::{PagedText,TextReadSource},ErasedSnapshotRetirement,retained_clone::{RetainedCloneGrant,RetainedCloneStep}};
 use semio_framework_dsl_record::{BorrowedFieldSpec as F,BorrowedRecordSpec as S,BorrowedShape as B,native_encoding::{FieldProjectionSource,FieldProjectionView as V}};
 struct Original;impl TextReadSource for Original{fn byte_len(&self)->usize{8194}fn byte_at(&self,index:usize)->Option<u8>{(index<8194).then_some(b'x')}}
 struct Label{value:PagedText<8194>}
 impl FieldProjectionSource for Label{fn projection_view(&self,path:&[usize])->Result<V<'_>,ValueError>{match path{[]=>Ok(V::Record(&[0])),[0]=>Ok(V::TextSource(self.value.read_view()?)),_=>Err(semio_framework_dsl_record::native_encoding::projection_path_error())}}}
 struct CanceledOutput<'a>{inner:&'a mut protocol::io::binary::operation_bytes::OwnedOperationBytes,accepted:&'a std::sync::atomic::AtomicUsize}
 impl protocol::io::binary::operation_bytes::OperationByteOutput for CanceledOutput<'_>{fn write_bytes(&mut self,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),PackRefusal>{for byte in bytes{protocol::io::binary::operation_bytes::OperationByteOutput::write_bytes(self.inner,&[*byte],control)?;self.accepted.fetch_add(1,std::sync::atomic::Ordering::Relaxed);}Ok(())}}
 static FIELDS:[F;1]=[F::new(0,"value",B::Text)];
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🌱️paged-origin/🔣️.json")).unwrap();
 struct Crossing<'a>{middle:&'a[u8]}impl TextReadSource for Crossing<'_>{fn byte_len(&self)->usize{8194}fn byte_at(&self,index:usize)->Option<u8>{if index>=8194{None}else if index>=4095&&index<4095+self.middle.len(){Some(self.middle[index-4095])}else{Some(b'x')}}}
 for unicode in fixture["unicode"].as_array().unwrap().iter().map(|text|text.as_str().unwrap()){let mut text=PagedText::<8194>::empty();let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);text.read_from_encoding_source(&Crossing{middle:unicode.as_bytes()},&mut control).unwrap();let((character,position),event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let view=text.read_view().unwrap();assert!(view.contiguous().is_none());let mut position=4095;let character=view.character_at(&mut position).unwrap();let mut buffer=[0;4];assert_eq!(view.copy_bytes(4095,&mut buffer[..unicode.len()]).unwrap(),unicode.len());assert_eq!(&buffer[..unicode.len()],unicode.as_bytes());(character,position)});assert_eq!(character,unicode.chars().next().unwrap());assert_eq!(position,4095+unicode.len());assert_eq!((event.requested_bytes,event.released_bytes),(0,0));let backing=text.allocated_bytes();let mut disposed=0;for _ in 0..32768{let(step,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||text.close_step(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_release_bytes:4096,maximum_depth:1,..Default::default()}).unwrap());let progress=match step{RetainedCloneStep::Progress(progress)|RetainedCloneStep::Complete(progress)=>progress};assert_eq!(event.requested_bytes,0);assert_eq!(event.released_bytes,progress.released_bytes);assert!(event.released_bytes<=4096&&event.largest_release_bytes<=4096);disposed+=event.released_bytes;if text.terminal_is_empty(){break}}assert!(text.terminal_is_empty());assert_eq!(disposed,backing);}
 for mode in fixture["modes"].as_array().unwrap().iter().map(|mode|mode.as_str().unwrap()){
  let mut label=Label{value:PagedText::empty()};assert!(label.value.read_view().is_err());let accepted=std::sync::atomic::AtomicUsize::new(0);let mut continuation=|_|mode!="interior256"||accepted.load(std::sync::atomic::Ordering::Relaxed)<256;let mut origin=NativeEncodeControl::new(if mode=="initial4096"{4096}else{65536},&mut continuation);
  let(result,constructed)=semio_framework_trace::observe_heap_allocations_on_this_thread(||label.value.read_from_encoding_source(&Original,&mut origin));
  assert!(!constructed.overflowed);assert_eq!(constructed.released_bytes,0);assert_eq!(constructed.requested_bytes,label.value.allocated_bytes());assert_eq!(constructed.requested_bytes,origin.owned_bytes());
  let original_backing=label.value.allocated_bytes();
  if mode=="initial4096"{assert!(result.is_err());assert!(label.value.read_view().is_err());assert!(label.value.byte_len()<8194);}
  else{
   result.unwrap();let view=label.value.read_view().unwrap();assert_eq!(view.len(),8194);for index in 0..8194{assert_eq!(view.byte_at(index),Some(b'x'));}
   let(mut capsule,birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||super::BorrowedProjectedPackOperation::from_source(&label,S{keyword:None,layout:RecordLayout::Inline,fields:&FIELDS}));assert_eq!((birth.requested_bytes,birth.released_bytes),(0,0));
   if mode=="complete"{let mut measurement=protocol::io::binary::operation_bytes::OperationByteMeasurement::new(8200);assert_eq!(fixture["metadataWindowBytes"],512);let window=origin.owned_bytes()+fixture["metadataWindowBytes"].as_u64().unwrap()as usize;let(result,metadata)=semio_framework_trace::observe_heap_allocations_on_this_thread(||origin.scoped_maximum(window,|control|capsule.write_body(&EncodeOptions::default(),&mut measurement,control)));assert_eq!(result.unwrap(),8200);assert_eq!((metadata.requested_bytes,metadata.released_bytes),(0,0));}
   let mut output=protocol::io::binary::operation_bytes::OwnedOperationBytes::try_new(8200,65536).unwrap();let mut options=EncodeOptions::default();options.limits.max_file_len=if mode=="file-one-short"{8199}else{8200};if mode=="depth-zero"{options.limits.max_depth=0;}
   let((result,diagnostic),encoded)=semio_framework_trace::observe_heap_allocations_on_this_thread(||match capsule.write_body(&options,&mut CanceledOutput{inner:&mut output,accepted:&accepted},&mut origin){Ok(bytes)=>(Ok(bytes),0),Err(error)=>{let error=error.into_value_error();let kind=error.kind;let diagnostic=match &error.message{std::borrow::Cow::Borrowed(_)=>0,std::borrow::Cow::Owned(message)=>message.capacity()};drop(error);(Err(kind),diagnostic)}});
   assert!(!encoded.overflowed);assert_eq!(label.value.allocated_bytes(),original_backing);assert_eq!(encoded.requested_bytes,capsule.allocated_bytes()+output.allocated_bytes()+diagnostic);assert_eq!(encoded.released_bytes,diagnostic);assert!(encoded.largest_release_bytes<=4096);assert_eq!(origin.owned_bytes(),original_backing+capsule.allocated_bytes()+output.allocated_bytes());assert!(origin.owned_bytes()<=65536);
   if mode=="complete"{assert_eq!(result.unwrap(),8200);let prefix=[0,1,0,7,130,64];for(index,byte)in prefix.into_iter().enumerate(){assert_eq!(output.byte_at(index),Some(byte));}for index in 6..8200{assert_eq!(output.byte_at(index),Some(b'x'));}}
   else{assert!(result.is_err());if mode=="interior256"{assert_eq!(accepted.load(std::sync::atomic::Ordering::Relaxed),256);assert_eq!(output.len(),256);}else{assert_eq!(output.len(),0);}}
   let scratch=capsule.allocated_bytes();let mut disposed=0;for _ in 0..32768{let(step,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||capsule.retire_one(1,4096).unwrap());assert!(!event.overflowed);assert_eq!(event.requested_bytes,0);assert_eq!(event.released_bytes,step.2);assert!(step.1<=1&&event.released_bytes<=4096&&event.largest_release_bytes<=4096);disposed+=event.released_bytes;if !step.0{break}}assert_eq!(disposed,scratch);assert_eq!(capsule.allocated_bytes(),0);drop(capsule);
   let output_backing=output.allocated_bytes();let mut disposed=0;for _ in 0..32768{let(step,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||output.close_one(1,4096).unwrap());assert_eq!(event.requested_bytes,0);assert!(!event.overflowed);assert!(event.released_bytes<=4096&&event.largest_release_bytes<=4096);match step{protocol::io::binary::operation_bytes::OperationByteCloseStep::Pending{released_items,released_bytes}=>{assert!(released_items<=1);assert_eq!(event.released_bytes,released_bytes);disposed+=released_bytes},protocol::io::binary::operation_bytes::OperationByteCloseStep::Complete=>{assert_eq!(event.released_bytes,0);break}}}assert_eq!(disposed,output_backing);assert!(output.terminal_is_empty());
  }
  let(step,zero)=semio_framework_trace::observe_heap_allocations_on_this_thread(||label.value.close_step(Default::default()).unwrap());assert!(matches!(step,RetainedCloneStep::Progress(_)|RetainedCloneStep::Complete(_)));assert_eq!((zero.requested_bytes,zero.released_bytes),(0,0));
  let mut disposed=0;for _ in 0..32768{let(step,event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||label.value.close_step(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_release_bytes:4096,maximum_depth:1,..Default::default()}).unwrap());assert!(!event.overflowed);assert_eq!(event.requested_bytes,0);assert!(event.released_bytes<=4096&&event.largest_release_bytes<=4096);let progress=match step{RetainedCloneStep::Progress(progress)=>progress,RetainedCloneStep::Complete(progress)=>progress};assert_eq!(event.released_bytes,progress.released_bytes);assert!(progress.copied_items<=1);disposed+=event.released_bytes;if label.value.terminal_is_empty(){break}}
  assert_eq!(disposed,original_backing);assert!(label.value.terminal_is_empty());assert!(label.value.read_view().is_err());let(_,drop_event)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(label));assert_eq!((drop_event.requested_bytes,drop_event.released_bytes),(0,0));
  eprintln!("[DEBUG] original paged semantic source mode={mode} logical8194 originalBacking={original_backing} disposed={disposed}; exact canonical body8200 and real1/4096 source/capsule/output events; original contiguous String and whole ChildEmit family unqualified");
 }
}
